/**
 * Inline SVG markup for an icon. Decorative by default (aria-hidden).
 *
 * @param string $name  Icon name.
 * @param int    $size  Width and height in pixels.
 * @param string $label Accessible label; when given the icon is announced.
 */
function bufan_icon( $name, $size = 20, $label = '' ) {
	$defs = bufan_icon_defs();
	if ( ! isset( $defs[ $name ] ) ) {
		return '';
	}
	list( $kind, $inner ) = $defs[ $name ];
	$paint = 'stroke' === $kind
		? 'fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round"'
		: 'fill="currentColor"';
	$a11y  = $label
		? sprintf( 'role="img" aria-label="%s"', esc_attr( $label ) )
		: 'aria-hidden="true" focusable="false"';
	return sprintf(
		'<svg class="icon icon-%1$s" width="%2$d" height="%2$d" viewBox="0 0 24 24" %3$s %4$s>%5$s</svg>',
		esc_attr( $name ),
		(int) $size,
		$paint,
		$a11y,
		$inner
	);
}
